/* @lc app=leetcode id=3729 lang=kotlin */ class Solution { fun g(a: Long, b: Long): Long = if (b == 0L) a else g(b, a % b) fun numGoodSubarrays(nums: IntArray, k: Int): Long = nums.runningFold(0L) { a, b -> a + b }.map { it % k }.groupingBy { it }.eachCount().values.sumOf { c -> c.toLong() * (c - 1) / 2 }.let { A -> (nums.indices.filter { it == 0 || nums[it] != nums[it - 1] } + nums.size).zipWithNext().fold(A) { acc, (s, e) -> (e - s).toLong().let { L -> (k / g(k.toLong(), nums[s].toLong())).let { t -> (L / t).let { m -> acc - (m * (L + 1) - t * m * (m + 1) / 2) + m } } } } } }